import React, { useState, useRef } from 'react';
import axios from 'axios';
import { API_URL } from '../utils/api';

const VideoProcessor = ({ colorblindType, mode }) => {
  const [selectedFile, setSelectedFile] = useState(null);
  const [processing, setProcessing] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const fileInputRef = useRef(null);

  const handleFileSelect = (e) => {
    const file = e.target.files[0];
    if (file) {
      setSelectedFile(file);
      setError(null);
      setSuccess(null);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    const file = e.dataTransfer.files[0];
    if (file && file.type.startsWith('video/')) {
      setSelectedFile(file);
      setError(null);
      setSuccess(null);
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const processVideo = async () => {
    if (!selectedFile) {
      setError('Please select a video file first');
      return;
    }

    const maxSize = 100 * 1024 * 1024; // 100MB
    if (selectedFile.size > maxSize) {
      setError(
        `Video file is too large (${(selectedFile.size / 1024 / 1024).toFixed(
          2
        )} MB). Maximum size is 100 MB.`
      );
      return;
    }

    setProcessing(true);
    setError(null);
    setSuccess(null);

    try {
      const formData = new FormData();
      formData.append('video', selectedFile);
      formData.append('colorblind_type', colorblindType);
      formData.append('mode', mode);

      const result = await axios.post(
        `${API_URL}/process-video`,
        formData,
        {
          headers: { 'Content-Type': 'multipart/form-data' },
          timeout: 300000, // 5 minutes
        }
      );

      if (result.data.success) {
        setSuccess(
          result.data.message ||
            'Video processed successfully. Download will start automatically.'
        );

        // ✅ CORRECT DOWNLOAD TRIGGER (THIS FIXES EVERYTHING)
        window.location.href = `${API_URL}/download/${result.data.output_file}`;
      } else {
        setError(result.data.error || 'Failed to process video');
      }
    } catch (err) {
      console.error(err);

      let errorMessage = 'Error processing video';
      if (err.response?.data?.error) {
        errorMessage = err.response.data.error;
      } else if (err.code === 'ECONNABORTED') {
        errorMessage =
          'Processing timed out. Try a smaller video or retry.';
      } else if (err.message) {
        errorMessage = err.message;
      }

      setError(errorMessage);
    } finally {
      setProcessing(false);
    }
  };

  return (
    <div className="component-container">
      <h2>Video Processor</h2>

      <div
        className="upload-area"
        onDrop={handleDrop}
        onDragOver={handleDragOver}
        onClick={() => fileInputRef.current?.click()}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept="video/*"
          onChange={handleFileSelect}
          hidden
        />
        <p>Click or drag and drop a video here</p>
        <p style={{ fontSize: '14px', color: '#666' }}>
          Supported formats: MP4, AVI, MOV
        </p>
      </div>

      {selectedFile && (
        <div style={{ marginTop: 15 }}>
          <p><strong>Selected file:</strong> {selectedFile.name}</p>
          <p>
            <strong>Size:</strong>{' '}
            {(selectedFile.size / 1024 / 1024).toFixed(2)} MB
          </p>
        </div>
      )}

      {error && (
        <div className="error">
          <strong>Error:</strong> {error}
        </div>
      )}

      {success && (
        <div className="success">
          <strong>Success:</strong> {success}
        </div>
      )}

      {processing && (
        <div className="loading">
          Processing video… this may take a while.
        </div>
      )}

      <div style={{ marginTop: 20, textAlign: 'center' }}>
        <button
          className="button"
          onClick={processVideo}
          disabled={!selectedFile || processing}
        >
          {processing ? 'Processing…' : 'Process Video'}
        </button>
      </div>
    </div>
  );
};

export default VideoProcessor;
